\pic[draw, "$93^{\circ}$", angle radius=0.4cm, angle eccentricity=2] {angle = E--C--D};
\pic[draw, "$x$", angle radius=0.45cm, angle eccentricity=2] {angle = B--A--D};
\end{tikzpicture}
[/tikz]

