\coordinate (C) at (-1.891,-0.651);
\coordinate (D) at (-0.382,-1.963);
\draw (A) -- (B);
\draw (B) -- (C);
\draw (C) -- (D);
\draw (D) -- (A);
\draw (O) circle (2);
\coordinate (E) at (0.136,2.238);
\draw (B) -- (E);
\node[left] at (A) {$A$};
\node[above] at (B) {$B$};
\node[right] at (C) {$C$};
\node[below] at (D) {$D$};
\node[above right] at (E) {$E$};
